module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel0, not_sel1;
    wire a0, a1, a2, a3;

    // Invert select signals
    not(not_sel0, sel[0]);
    not(not_sel1, sel[1]);

    // AND terms for each input
    and(a0, in[0], not_sel1, not_sel0);
    and(a1, in[1], not_sel1, sel[0]);
    and(a2, in[2], sel[1], not_sel0);
    and(a3, in[3], sel[1], sel[0]);

    // Combine all terms with OR
    or(out, a0, a1, a2, a3);
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in0, not_in1;

    // Generate inverted inputs using NOT gates
    not (not_in1, in[1]);
    not (not_in0, in[0]);

    // Generate each output using AND gates
    and (out[0], not_in1, not_in0);
    and (out[1], not_in1, in[0]);
    and (out[2], in[1], not_in0);
    and (out[3], in[1], in[0]);

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])
        code = 2'b11;
    else if (in[2])
        code = 2'b10;
    else if (in[1])
        code = 2'b01;
    else
        code = 2'b00;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

parameter [1:0] STATE_A = 2'b00,
                STATE_B = 2'b01,
                STATE_C = 2'b11,
                STATE_D = 2'b10;

reg [1:0] current_state, next_state;

always @(posedge clk) begin
    if (reset)
        current_state <= STATE_A;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        STATE_A: next_state = STATE_B;
        STATE_B: next_state = STATE_C;
        STATE_C: next_state = STATE_D;
        STATE_D: next_state = STATE_D;
        default: next_state = STATE_A;
    endcase
end

assign state = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

localparam GREEN  = 2'b00,
           YELLOW = 2'b01,
           RED    = 2'b10;

reg [1:0] current_state, next_state;

always @(posedge clk) begin
    if (reset)
        current_state <= GREEN;
    else
        current_state <= next_state;
end

always @* begin
    case (current_state)
        GREEN:  next_state = YELLOW;
        YELLOW: next_state = RED;
        RED:    next_state = GREEN;
        default:next_state = GREEN;
    endcase
end

assign light = (current_state == GREEN) ? 3'b100 :
               (current_state == YELLOW) ? 3'b010 :
               3'b001;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Define state parameters
    localparam [1:0] UP    = 2'b00,
                     DOWN  = 2'b01,
                     STOP  = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential state update with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= UP;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational next state logic
    always @* begin
        case (current_state)
            UP: begin
                next_state = down_request ? DOWN : UP;
            end
            DOWN: begin
                next_state = up_request ? UP : DOWN;
            end
            STOP: begin
                if (up_request && down_request) begin
                    next_state = STOP;
                end else if (up_request) begin
                    next_state = UP;
                end else if (down_request) begin
                    next_state = DOWN;
                end else begin
                    next_state = STOP;
                end
            end
            default: begin
                next_state = UP;
            end
        endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] NOT_MONEY = 2'b00,
                     MONEY     = 2'b01,
                     ITEM      = 2'b10;

    reg [1:0] state_reg;

    // Next state logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= NOT_MONEY;
        end else begin
            case (state_reg)
                NOT_MONEY: 
                    if (coin_inserted)
                        state_reg <= MONEY;
                MONEY: 
                    if (item_selected)
                        state_reg <= ITEM;
                ITEM: 
                    state_reg <= NOT_MONEY;
                default: 
                    state_reg <= NOT_MONEY;
            endcase
        end
    end

    assign state = state_reg;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    reg signed [15:0] Y_reg;
    reg signed [15:0] A_reg;
    reg signed [15:0] Q_reg;
    reg Q_minus;
    reg [4:0] counter;
    integer i;

    always @* begin
        Y_reg = 16'sd0;
        A_reg = 16'sd0;
        Q_reg = in_0;
        Q_minus = 1'sd0;
        counter = 5'sd0;

        for (i = 0; i < 8; i = i + 1) begin
            if (in_1[i]) begin
                if (counter > 0) begin
                    A_reg = A_reg + Q_reg;
                    Q_reg = Q_reg - Q_minus;
                end
                Y_reg = Y_reg + (Q_reg << i);
            end
            Q_minus = Q_reg[0];
            Q_reg = Q_reg >> 1;
            counter = counter - 1;
        end

        Y_reg = Y_reg + (Q_reg << 1);
    end

    assign out = Y_reg;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [3:0] tens;
wire [3:0] units;

assign tens = (in_0[15:12] >= 4'd1) ? 4'd1 :
              (in_0[15:12] <= -4'd2) ? 4'd2 : 4'd0;

assign units = (in_0[11:8] == 4'd1) ? 4'd1 :
               (in_0[11:8] == 4'd2) ? 4'd2 :
               (in_0[11:8] == 4'd3) ? 4'd3 : 4'd0;

assign out = {4'b0, tens};

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    wire signed [7:0] b_adj = b + 8'd128; // Convert to two's complement
    wire signed [8:0] sum = a + b_adj;
    assign out = sum + 9'sd1;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);

wire [7:0] pp0, pp1, pp2, pp3;

assign pp0 = {4'b0, (a & {4{b[0]}})} << 0;
assign pp1 = {4'b0, (a & {4{b[1]}})} << 1;
assign pp2 = {4'b0, (a & {4{b[2]}})} << 2;
assign pp3 = {4'b0, (a & {4{b[3]}})} << 3;

assign #100 out = pp0 + pp1 + pp2 + pp3;

endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

    assign and_out = a & b;
    assign or_out  = a | b;
    assign xor_out = a ^ b;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = in << shift;

endmodule

module bitwise_not (
    input [7:0] in,
