endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    wire [7:0] stage0_out, stage1_out;

    // Stage 0: Shift by 1 bit if shift[0] is set
    assign stage0_out = shift[0] ? {in[6:0], 1'b0} : in;

    // Stage 1: Shift by 2 bits if shift[1] is set
    assign stage1_out = shift[1] ? {stage0_out[5:0], 2'b00} : stage0_out;

    // Stage 2: Shift by 4 bits if shift[2] is set
    assign out = shift[2] ? {stage1_out[3:0], 4'h0} : stage1_out;
endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

assign out = in_0[15] ? 16'sd0 : in_0;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out = data_in + 4;

endmodule

module modular_add_cipher (
    input [7:0] data_in,
