endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [7:0] expanded_data;
    wire [7:0] expanded_key;

    // Expansion of data_in (each bit duplicated)
    assign expanded_data = {data_in[0], data_in[0], data_in[1], data_in[1], 
                            data_in[2], data_in[2], data_in[3], data_in[3],
                            data_in[4], data_in[4], data_in[5], data_in[5],
                            data_in[6], data_in[6], data_in[7], data_in[7]};

    // Expansion of KEY (each bit duplicated)
    assign expanded_key = {KEY[0], KEY[0], KEY[1], KEY[1], 
                           KEY[2], KEY[2], KEY[3], KEY[3]};

    // Compute each bit of data_out using XOR and expansion sequences
    assign data_out[0] = expanded_data[0] ^ expanded_key[0];
    assign data_out[1] = expanded_data[1] ^ expanded_key[1];
    assign data_out[2] = expanded_data[2] ^ expanded_key[2];
    assign data_out[3] = expanded_data[3] ^ expanded_key[3];
    assign data_out[4] = expanded_data[4] ^ expanded_key[0];
    assign data_out[5] = expanded_data[5] ^ expanded_key[1];
    assign data_out[6] = expanded_data[6] ^ expanded_key[2];
    assign data_out[7] = expanded_data[7] ^ expanded_key[3];

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

reg [31:0] counter;

always @(posedge clk) begin
    if (rst) begin
        counter <= 32'd0;
    end else begin
        counter <= counter + 32'd1;
    end
end

assign clk_out = counter[0];

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

wire [3:0] a_gt_b;
wire [3:0] a_eq_b;
wire [3:0] a_lt_b;

assign a_gt_b[3] = 1'b1;
assign a_eq_b[3] = (a[3] == b[3]);
assign a_lt_b[3] = (a[3] < b[3]);

genvar i;
generate
    for (i = 2; i >= 0; i = i - 1) begin : gen_comparator
        assign a_gt_b[i] = a[i] & ~b[i] | (a_gt_b[i+1] & a_eq_b[i]);
        assign a_eq_b[i] = (a[i] == b[i]) & a_eq_b[i+1];
        assign a_lt_b[i] = ~a[i] | (a_eq_b[i] & a_lt_b[i+1]);
    end
endgenerate

assign gt = a_gt_b[0];
assign eq = a_eq_b[0];
assign lt = a_lt_b[0];

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

assign out = enable ? (4'b0001 << in) : 4'b0000;

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    assign out0 = in & ~sel;
    assign out1 = in & sel;

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    // Outgoing signals
    assign out0 = (sel == 2'b00) ? in : 1'b0;
    assign out1 = (sel == 2'b01) ? in : 1'b0;

    // Incoming signals
    assign out2 = (sel == 2'b10) ? in : 1'b0;
    assign out3 = (sel == 2'b11) ? in : 1'b0;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] binary_counter;

always @(posedge clk) begin
    if (rst) begin
        binary_counter <= 8'b0;
    end else begin
        binary_counter <= binary_counter + 1;
    end
end

assign count = binary_counter ^ (binary_counter >> 1);

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;
wire [3:0] d;

assign d[0] = ~q_reg[0];
assign d[1] = q_reg[0];
assign d[2] = q_reg[1];
assign d[3] = q_reg[2];

assign q = q_reg;

always @(posedge clk) begin
    if (rst)
        q_reg <= 4'b0000;
    else
        q_reg <= d;
end

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst)
        shift_reg <= 8'b0;
    else if (load)
        shift_reg <= pin;
    else
        shift_reg <= shift_reg << 1;
end

assign sout = shift_reg[7];

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);
    assign valid = |in;
    assign out[1] = in[3] | in[2];
    assign out[0] = in[3] | (in[1] & ~in[2]);
endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 4'b0001;
    end else begin
        q_reg <= {q_reg[2], q_reg[1], q_reg[0], q_reg[3]};
    end
end

assign q = q_reg;

endmodule

module sipo_8bit(
