module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
    reg [7:0] count_reg;

    assign count = count_reg;

    always @(posedge clk) begin
        if (rst) begin
            count_reg <= 8'd0;
        end else begin
            count_reg <= count_reg + 8'd1;
