module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] idle  = 2'b00,
                   state1 = 2'b01,
                   state2 = 2'b10,
                   state3 = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      current_state <= idle;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      idle:  next_state = (r == 3'b000) ? state1 : idle;
      state1: next_state = (r == 3'b000) ? state2 : state1;
      state2: next_state = (r == 3'b111) ? state3 : state2;
      state3: next_state = (r == 3'b111) ? state1 : state3;
      default: next_state = idle;
    endcase
  end

  assign g = (current_state == state1) ? r :
             (current_state == state2) ? 3'b000 :
             (current_state == state3) ? 3'b111 :
             3'b000;

endmodule

module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);

  always @(posedge clk) begin
    if (E || L)
      Q <= (L) ? R : w;
  end

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);
  wire t1, t2, t3, t4, t5, t6, t7, t8, t9, t10;

  assign t1 = ~(p1a & p1b);
  assign t2 = ~(t1 & p1c);
  assign t3 = ~(t2 & p1d);
  assign t4 = ~(t3 & t3);
  assign p1y = t4;

  assign t5 = ~(p2a & p2b);
  assign t6 = ~(t5 & p2c);
  assign t7 = ~(t6 & p2d);
  assign t8 = ~(t7 & t7);
  assign p2y = t8;

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire w1, w2, w3, w4, w5, w6;
  wire w7, w8, w9, w10, w11, w12;

  assign w1 = p1a & p1b;
  assign w2 = w1 & p1c;
  assign w3 = ~p1d;
  assign w4 = p1e & w3;
  assign w5 = w4 & p1f;
  assign w6 = ~p2a;
  assign w7 = p2b & w6;
  assign w8 = w7 & p2c;
  assign w9 = p2d & w8;
  assign w10 = ~w7;
  assign w11 = ~w10 & p2c;
  assign w12 = w9 | w11;

  assign p1y = w2 | w5;
  assign p2y = w12;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  // Regular assignment
  assign out_assign = a & b;

  // Always block simulation
  always @(*) begin
    out_alwaysblock = a & b;
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);

  // Combinational logic using assign statement
  assign out_assign = a ^ b;

  // Sequential block with always combinational reassignment
  always @(*) begin
    out_always_comb = a ^ b;
  end

  // Sequential block with always keyword and flip-flop behavior
  always @(posedge clk) begin
    out_always_ff <= a ^ b;
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire b_mux;

  // Multiplexer for b signal based on sel_b1 and sel_b2
  assign b_mux = (sel_b1 & sel_b2) ? a : b;

  // Assign outputs
  assign out_assign = b_mux;

  // Register b_mux with clock and reset
  always @(posedge clk or posedge reset) begin
    if (reset)
      out_always <= 1'b0;
    else
      out_always <= b_mux;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  // Rule 1: If CPU is overheated, shut it off immediately
  always @(*) begin
    if (cpu_overheated)
      shut_off_computer = 1'b1;
    else
      shut_off_computer = 1'b0;
  end

  // Rule 2: Keep driving if current location isn't the final destination
  always @(*) begin
    if (arrived)
      keep_driving = 1'b0;
    else if (gas_tank_empty)
      keep_driving = 1'b0;
    else
      keep_driving = 1'b1;
  end

endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

always @(*) begin
  // Initialize all directions to 0
  left = 1'b0;
  down = 1'b0;
  right = 1'b0;
  up = 1'b0;

  case (scancode)
    // Left arrow key (ASCII 0x41)
    16'h0041: left = 1'b1;
    // Down arrow key (ASCII 0x53)
    16'h0053: down = 1'b1;
    // Right arrow key (ASCII 0x44)
    16'h0044: right = 1'b1;
    // Up arrow key (ASCII 0x52)
    16'h0052: up = 1'b1;
  endcase
end

endmodule

