module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire [3:0] T;

  assign T[0] = 1'b1;
  assign T[1] = ~q[0];
  assign T[2] = (~q[0]) & (~q[1]);
  assign T[3] = (~q[0]) & (~q[1]) & (~q[2]);

  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin : gen_toggle
      always @(posedge clk) begin
        if (reset)
          q[i] <= 1'b0;
        else
          q[i] <= q[i] ^ T[i];
      end
    end
