  parameter MOVING = 2'b10;
  parameter STOPPED = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  always @(*) begin
    case (current_state)
      IDLE: begin
        next_state = (train_valid && !train_taken) ? MOVING : IDLE;
      end
      MOVING: begin
        next_state = (train_valid && train_taken) ? STOPPED : MOVING;
      end
      STOPPED: begin
        next_state = STOPPED;
      end
      default: next_state = IDLE;
    endcase
  end

  assign state = current_state;

