  localparam S1 = 2'b01;
  localparam S2 = 2'b10;

  reg [1:0] current_state, next_state;

  // State register with asynchronous active-low reset
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = x ? S0 : S1;
      S1: next_state = x ? S0 : S2;
      S2: next_state = x ? S0 : S2;
      default: next_state = S0;
    endcase
  end

  // Output logic (Mealy: depends on current state and input)
  always @(*) begin
    z = (current_state == S2) && x;
  end

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p; // Propagate terms (a XOR b)
  wire [7:0] g; // Generate terms (a NAND b)
  wire [7:0] k; // Intermediate carry terms
  wire [8:0] c; // Carry chain (c[0] = 0)

  assign c[0] = 1'b0;

  // 8-bit ripple carry adder with optimized PDP
  generate
    genvar i;
    for (i=0; i<8; i=i+1) begin: BIT
      assign p[i] = a[i] ^ b[i];
      assign g[i] = ~(a[i] & b[i]);
      assign k[i] = (p[i] & c[i]) | (g[i] & c[i-1]);
      assign c[i+1] = k[i] ^ c[i];
      assign s[i] = p[i] ^ c[i];
    end
  endgenerate

  assign overflow = c[8] ^ c[7]; // Overflow based on MSB carry in/out

endmodule

