      current_state <= S0;
      done_reg <= 1'b0;
    end else begin
      current_state <= next_state;
      done_reg <= (current_state == S3) ? 1'b1 : 1'b0;
    end
  end

  always @* begin
    case (current_state)
      S0: next_state = in[3] ? S1 : S0;
      S1: next_state = in[3] ? S1 : S2;
      S2: next_state = in[3] ? S3 : S0;
