module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam [1:0] RST = 2'b00,
                   S0 = 2'b01,
                   S1 = 2'b10,
                   DONE = 2'b11;

  reg [1:0] current_state, next_state;
  reg [2:0] counter;
  reg done_reg;

  // State transition
  always @(posedge clk) begin
    if (reset)
      current_state <= RST;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      RST: next_state = in ? S0 : RST;
      S0: next_state = in ? S1 : S0;
      S1: next_state = in ? DONE : S1;
      DONE: next_state = DONE;
      default: next_state = RST;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (reset)
      counter <= 3'b0;
    else if (current_state == S1)
      counter <= counter + 1;
    else
      counter <= 3'b0;
  end

  // Done signal logic
  always @(posedge clk) begin
    if (reset)
      done_reg <= 1'b0;
    else
      done_reg <= (current_state == DONE) ? 1'b1 : (counter == 3'd7) ? 1'b1 : 1'b0;
  end

  assign done = done_reg;

endmodule

