      WALK_LEFT:  next_state = bump_right ? WALK_RIGHT : WALK_LEFT;
      default:    next_state = WALK_RIGHT;
    endcase
  end

  always @(posedge clk, posedge areset) begin
    if (areset) begin
      current_state <= WALK_RIGHT;
