module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam [1:0] stop = 2'b00,
                   left = 2'b01,
                   right = 2'b10,
                   special = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= stop;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      stop: begin
        if (bump_left & ground)
          next_state = left;
        else if (bump_right & ground)
          next_state = right;
        else
          next_state = stop;
      end
      left: begin
        if (ground)
          next_state = left;
        else
          next_state = stop;
      end
      right: begin
        if (ground)
          next_state = right;
        else
          next_state = stop;
      end
      special: begin
        if (ground)
          next_state = special;
        else
          next_state = stop;
      end
      default: next_state = stop;
    endcase
  end

  assign walk_left = (current_state == left);
  assign walk_right = (current_state == right);
  assign aaah = (current_state == left) || (current_state == right);

endmodule

