module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Signals in clk_a domain
	reg [3:0] data_reg;
	reg sync_en_a;

	// Signals in clk_b domain
	reg sync_en_b;
	reg [3:0] data_reg_b;

	// Synchronization and data capture in clk_a
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
			sync_en_a <= 1'b0;
		end else begin
			sync_en_a <= data_en;
			data_reg <= {data_in[3:1], data_en}; // Shift in data_in[3:1] and insert data_en as LSB
		end
	end

	// Synchronization and data capture in clk_b
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_en_b <= 1'b0;
			data_reg_b <= 4'b0;
		end else begin
			// Synchronize sync_en_a from clk_a to clk_b domain
			sync_en_b <= sync_en_a;
			// Capture data when sync_en_b is high
			if (sync_en_b) begin
				data_reg_b <= data_reg;
			end
		end
	end

	// Output the synchronized data
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
	 end else if (sync_en_b) begin
		 dataout <= data_reg_b;
		end
	end

endmodule

