          s1 = 2'b01,
          s2 = 2'b10,
          s3 = 2'b11;

// State transition and counter logic
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= s0;
        counter <= 2'b00;
    end else begin
        state <= next_state;
        if (state == s3)
            counter <= counter + 1;
        else
            counter <= 2'b00;
    end
end

// Next state logic
always @(*) begin
    case (state)
        s0: next_state = IN ? s1 : s0;
        s1: next_state = IN ? s1 : s2;
        s2: next_state = IN ? s3 : s0;
        s3: next_state = (counter == 2'b10) ? s0 : s3;
        default: next_state = s0;
    endcase
end

// Output logic
always @(posedge CLK or posedge RST) begin
    if (RST)
        MATCH <= 1'b0;
    else
        MATCH <= (state == s3) && (counter == 2'b10);
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] count;
reg [3:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 4'b0;
        shift_reg <= 4'b0;
    end else begin
        count <= (count == 4'd15) ? 4'b0 : count + 1;
        if (count == 4'd15) begin
            shift_reg <= d;
        end else begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end
    end
end

assign valid_out = (count == 4'd15);
assign dout = shift_reg[0];

endmodule

