module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     localparam [1:0] s0 = 2'b00,
                      s1 = 2'b01,
                      s2 = 2'b10,
                      s3 = 2'b11;

     reg [1:0] current_state, next_state;
     reg [1:0] prev_state;

     // State register with asynchronous reset
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             current_state <= s0;
         end else begin
             current_state <= next_state;
         end
     end

     // Previous state register to track transitions
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             prev_state <= s0;
         end else begin
             prev_state <= current_state;
         end
     end

     // Next state logic
     always @(*) begin
         case (current_state)
             s0: next_state = data_in ? s0 : s1;
             s1: next_state = data_in ? s2 : s1;
             s2: next_state = data_in ? s3 : s1;
             s3: next_state = s0; // Reset to s0 after s3
             default: next_state = s0;
         endcase
     end

     // Output logic: sequence_detected when transitioning from s3 to s0
     assign sequence_detected = (prev_state == s3) && (current_state == s0);

endmodule
